UGreeter::UGreeter(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	Name = TEXT("World");
	Scale = 2.5f;
	bLoud = true;
	Tint = FLinearColor(1.0f, 0.5f, 0.0f, 1.0f);
	Mood = EMood::Excited;
}

void* UGreeter::FerrealState() const
{
	if (!FerrealStatePtr)
	{
		Ferreal::HelloRust::Register();
		FerrealStatePtr = ferreal_HelloRust_Greeter_new(static_cast<UObject*>(const_cast<UGreeter*>(this)));
	}
	return FerrealStatePtr;
}

void UGreeter::BeginDestroy()
{
	if (FerrealStatePtr)
	{
		ferreal_HelloRust_Greeter_drop(FerrealStatePtr);
		FerrealStatePtr = nullptr;
	}
	Super::BeginDestroy();
}

